list_tax_country_taxes.code:
final response = await client.taxCountryTaxes
    .listTaxCountryTaxes(queryParams: {'limit': 20});
final countryTaxes = (response.map as Map)['country_taxes'] as List;
for (final countryTax in countryTaxes) {
  print('${(countryTax as Map)['id']} ${countryTax['name']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print(pagination['total']);

create_tax_country_tax.code:
final response = await client.taxCountryTaxes.createTaxCountryTax({
  'country_tax': {
    'country_code': 'NZ',
    'name': 'New Zealand',
    'tax_rate': 4.5,
    'tax_method': 'FIXED_RATE',
    'is_default': false,
  },
});
final countryTax = (response.map as Map)['country_tax'] as Map;
print(countryTax['id']);

get_tax_country_tax.code:
final response = await client.taxCountryTaxes.getTaxCountryTax(4);
final countryTax = (response.map as Map)['country_tax'] as Map;
print('${countryTax['name']} ${countryTax['rate_display']}');
final stateRules = countryTax['state_rules'] as List;
for (final stateRule in stateRules) {
  print('${(stateRule as Map)['id']} ${stateRule['tax_rule']}');
}

update_tax_country_tax.code:
final response = await client.taxCountryTaxes.updateTaxCountryTax(42, {
